<?php
require 'includes/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$cat=post_str('category',100);$amt=post_num('amount');$date=$_POST['expense_date']??date('Y-m-d');if($cat&&$amt>0){$s=$pdo->prepare('INSERT INTO expenses(branch_id,category,description,amount,expense_date,user_id) VALUES(?,?,?,?,?,?)');$s->execute([$branchId,$cat,post_str('description',255),$amt,$date,$_SESSION['user']['id']]);audit($pdo,'expense.created',$cat.' '.money($amt));flash('success','Expense saved.');}redirect('expenses.php');}
$s=$pdo->prepare('SELECT * FROM expenses WHERE branch_id=? ORDER BY expense_date DESC,id DESC LIMIT 100');$s->execute([$branchId]);$rows=$s->fetchAll();page_header('Expenses');
?><section class="panel"><h2>Record expense</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><div><label>Category</label><input name="category" required placeholder="Rent, transport, utilities"></div><div><label>Description</label><input name="description"></div><div><label>Amount</label><input type="number" min=".01" step=".01" name="amount" required></div><div><label>Date</label><input type="date" name="expense_date" value="<?=date('Y-m-d')?>"></div><div><button>Save expense</button></div></div></form></section>
<section class="panel"><h2>Recent expenses</h2><div class="table-wrap"><table><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['expense_date'])?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach?></table></div></section><?php page_footer();?>
